SELECT
	COUNT(*)
FROM
	READING_NOTES
WHERE
	homepage_id = #{homepage_id}

AND	member_id = #{member_id}


AND	approve_status = #{approve_status_search}


AND	book_type = #{book_type}


AND	${search_type} LIKE '%${search_text}%'

SELECT homepage_id, reading_notes_idx, member_id, member_name, user_no, book_name, book_type, publisher, author, isbn, contents, approve_status, cancel_reason, read_success_date, add_date, modify_date FROM READING_NOTES WHERE homepage_id = #{homepage_id}
AND member_id = #{member_id}
AND approve_status = #{approve_status_search}
AND book_type = #{book_type}
AND ${search_type} LIKE '%${search_text}%'
ORDER BY reading_notes_idx DESC

SELECT
	homepage_id, reading_notes_idx, member_id, member_name, user_no,
	book_name, book_type, publisher, author, isbn,
	contents, approve_status, cancel_reason, read_success_date, add_date,
	modify_date
FROM
	READING_NOTES
WHERE
	homepage_id = #{homepage_id}

AND	approve_status = #{approve_status_search}


AND	book_type = #{book_type}


AND	${search_type} = #{search_text}

ORDER BY reading_notes_idx DESC

SELECT
	homepage_id, reading_notes_idx, member_id, book_name, book_type,
	publisher, author, isbn, contents, approve_status,
	cancel_reason, read_success_date, add_date, modify_date
FROM
	READING_NOTES
WHERE
	homepage_id = #{homepage_id}
AND	member_id = #{member_id}
AND	reading_notes_idx = #{reading_notes_idx}

